// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/integer_overflow_mapping_sym_1.sol";

contract IntegerOverflowTest is Test {
    IntegerOverflowMappingSym1 public overflowContract;

    function setUp() public {
        overflowContract = new IntegerOverflowMappingSym1();
    }

    function testInitialUnderflow() public {
        uint256 key = 1;
        uint256 initialValue = 100;

        // First init will underflow from 0 to type(uint256).max - initialValue + 1
        overflowContract.init(key, initialValue);

        // Verify the underflow occurred
        uint256 expectedValue = type(uint256).max - initialValue + 1;
        assertEq(overflowContract.getMapValue(key), expectedValue);
    }

    function testSubsequentUnderflow() public {
        uint256 key = 2;
        uint256 firstValue = 100;
        uint256 secondValue = 50;

        // First operation causes initial underflow
        overflowContract.init(key, firstValue);
        uint256 firstExpected = type(uint256).max - firstValue + 1;
        assertEq(overflowContract.getMapValue(key), firstExpected);

        // Second operation subtracts more
        overflowContract.init(key, secondValue);

        // Verify the new underflow value
        uint256 secondExpected = firstExpected - secondValue;
        assertEq(overflowContract.getMapValue(key), secondExpected);
    }

    function testLargeUnderflow() public {
        uint256 key = 3;
        uint256 hugeValue = type(uint256).max - 100;

        // Subtract almost the entire range
        overflowContract.init(key, hugeValue);

        // Should wrap around to a small positive number
        uint256 expectedValue = type(uint256).max - hugeValue + 1;
        assertEq(overflowContract.getMapValue(key), expectedValue);

        // Verify user operation count increased despite underflow
        assertEq(overflowContract.getUserOperationCount(address(this)), 1);
    }
}
